'use strict';
// Monochromatic recoloring: common hue, source lightness, related saturation.
function rgbToHsl(values){const [r,g,b]=values.map(v=>v/255),hi=Math.max(r,g,b),lo=Math.min(r,g,b),d=hi-lo,l=(hi+lo)/2;let h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));if(hi===r)h=((g-b)/d)%6;else if(hi===g)h=(b-r)/d+2;else h=(r-g)/d+4;h=((h*60)%360+360)%360}return {h,s,l}}
function hslToRgb(h,s,l){const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let p=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return p.map(v=>Math.max(0,Math.min(255,Math.round((v+m)*255))))}
function tintHex(hex,options){if(hex===null)return null;const original=rgb(hex),source=rgbToHsl(original),target=rgbToHsl(rgb(options.color));if(options.strength===0||(options.preserveNeutral&&(source.s<.12||source.l<.06||source.l>.97)))return hex;const saturation=Math.min(1,target.s*(.7+.3*source.s)*options.saturation),changed=hslToRgb(target.h,saturation,source.l),mix=original.map((v,i)=>Math.round(v+(changed[i]-v)*options.strength));return '#'+mix.map(v=>v.toString(16).padStart(2,'0')).join('')}
function tintOptions(){return {color:$('tintColor').value,strength:Number($('tintStrength').value)/100,saturation:Number($('tintSaturation').value)/100,preserveNeutral:$('tintPreserveNeutral').checked}}
function tintPixelArray(pixels,options){const cache=new Map();return pixels.map(p=>{if(p===null)return null;if(!cache.has(p))cache.set(p,tintHex(p,options));return cache.get(p)})}
function tintScopeAvailable(scope){if(scope==='layer'&&!composition.layers[compositionSelected])throw Error('请在组合工作台选择一个图层');if(scope==='layers'&&!composition.layers.length)throw Error('组合工作台还没有图层')}
function tintPreviewData(scope,options){tintScopeAvailable(scope);if(scope==='layer'){const l=composition.layers[compositionSelected],before=transformObject(l),after=transformObject({...l,pixels:tintPixelArray(l.pixels,options)});return {w:before.w,h:before.h,before:before.pixels,after:after.pixels}}if(scope==='layers'){const colored={...composition,layers:composition.layers.map(l=>({...l,pixels:tintPixelArray(l.pixels,options)}))};return {w:composition.width,h:composition.height,before:composeObjects(composition),after:composeObjects(colored)}}const before=state.frames[current].map(p=>p===null?null:colorOf(p));return {w:state.width,h:state.height,before,after:tintPixelArray(before,options)}}
function renderTintPreview(){$('tintStrengthLabel').textContent=$('tintStrength').value+'%';$('tintSaturationLabel').textContent=$('tintSaturation').value+'%';try{const d=tintPreviewData($('tintScope').value,tintOptions()),size=Math.max(1,Math.min(8,Math.floor(300/Math.max(d.w,d.h))));drawObjectPixels($('tintBefore'),d.before,d.w,d.h,size);drawObjectPixels($('tintAfter'),d.after,d.w,d.h,size);$('tintApply').disabled=false;$('tintStatus').textContent='预览显示当前帧或组合；只在点击应用后改色。'}catch(e){$('tintBefore').width=1;$('tintAfter').width=1;$('tintApply').disabled=true;$('tintStatus').textContent=e.message}}
function openTintDialog(fromComposition=false){if(floating&&!fromComposition){notice('请先确认或取消待粘贴图块，再染色');return}stop();$('tintScope').value=fromComposition?(compositionSelected>=0?'layer':'layers'):'frame';$('tintDialog').showModal();renderTintPreview()}
$('openTint').onclick=()=>openTintDialog();$('compositionTint').onclick=()=>openTintDialog(true);$('tintCancel').onclick=()=>$('tintDialog').close();for(const id of ['tintColor','tintStrength','tintSaturation','tintPreserveNeutral','tintScope'])$(id).addEventListener(id==='tintScope'?'change':'input',renderTintPreview);document.querySelectorAll('[data-tint]').forEach(b=>{b.style.borderColor=b.dataset.tint;b.onclick=()=>{$('tintColor').value=b.dataset.tint;renderTintPreview()}});
function tintProjectFrames(project,indices,options){const palette=project.palette.map(p=>({...p})),used=new Set(palette.map(p=>p.code)),byHex=new Map(palette.map(p=>[p.hex.toLowerCase(),p.code])),byCode=new Map(palette.map(p=>[p.code,p.hex])),mapping=new Map();const frames=project.frames.slice();for(const index of indices){frames[index]=project.frames[index].map(code=>{if(code===null)return null;if(mapping.has(code))return mapping.get(code);const hex=tintHex(byCode.get(code),options).toLowerCase();if(hex===byCode.get(code).toLowerCase()){mapping.set(code,code);return code}let replacement=byHex.get(hex);if(!replacement){let n=1;while(used.has('T'+String(n).padStart(3,'0')))n++;replacement='T'+String(n).padStart(3,'0');used.add(replacement);byHex.set(hex,replacement);palette.push({code:replacement,hex})}mapping.set(code,replacement);return replacement})}if(palette.length>1000)throw Error('染色后超过 1000 色，请先精简色卡');return {palette,frames}}
$('tintApply').onclick=guarded(()=>{const scope=$('tintScope').value,options=tintOptions();tintScopeAvailable(scope);if(options.strength===0){$('tintDialog').close();return}if(scope==='layer'||scope==='layers'){compositionCheckpoint();const indices=scope==='layer'?[compositionSelected]:composition.layers.map((_,i)=>i);indices.forEach(i=>{const layer=composition.layers[i];layer.pixels=tintPixelArray(layer.pixels,options)});saveCompositionLocal();if($('composer').open)compositionRender();notice('组合色系已统一，可在工作台撤销')}else{const indices=scope==='frames'?state.frames.map((_,i)=>i):[current],result=tintProjectFrames(state,indices,options);checkpoint();state.palette=result.palette;state.frames=result.frames;sync();render();persist();notice('已统一色系，保留明暗层次；可撤销')}$('tintDialog').close()});
